mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p - vec3(0.0, 0.2, 0.0);
  q.xz = rot(time * 0.4) * q.xz;
  q.yz = rot(time * 0.25) * q.yz;
  float oct = dot(abs(q), vec3(0.57735)) - 0.9;
  float sea = p.y + 1.2 + 0.05 * sin(p.x * 4.0 + time * 2.0) * cos(p.z * 4.0);
  return min(oct, sea);
}
shader_body {
