  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.04, 0.0, 0.02);
