    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.0, 2.0, -1.5));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    col = vec3(0.18, 0.01, 0.04) + diff * vec3(1.0, 0.1, 0.25) + spec * vec3(1.0, 0.8, 0.9) + rim * vec3(1.0, 0.2, 0.4);
  }
  col += glow * vec3(1.0, 0.1, 0.3) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
